def group_anagrams(words):
    """Group a list of strings into anagram families.  Input: list[str]; Output: list[list[str]].

    >>> group_anagrams(['listen', 'silent', 'enlist'])
    """
    # Edge case: return empty list for empty input
    if not words:
        return []

    # Use a dict mapping the sorted character tuple to the list of words sharing that signature
    buckets = {}
    for w in words:
        key = tuple(sorted(w))
        buckets.setdefault(key, []).append(w)

    # Return the groups; order is intentionally unspecified
    return list(buckets.values())
```

