def run_length_encode(s: str) -> str:
    if not s:
        return ""
    result = []
    prev, count = s[0], 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(f"{prev}{count}")
            prev, count = ch, 1
    result.append(f"{prev}{count}")
    return "".join(result)
