def parse_config(text):
    """Parse simple key=value configuration text into a dict, converting ints and booleans."""
    config = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            continue
        key, val = map(str.strip, line.split('=', 1))
        low = val.lower()
        if low == 'true':
            parsed = True
        elif low == 'false':
            parsed = False
        else:
            # Support signed integers (e.g., "+42" or "-7")
            if val.lstrip('+-').isdigit():
                parsed = int(val)
            else:
                parsed = val
        config[key] = parsed
    return config
```

