def is_prime(n):
    if n <= 1:
        return False
    # Early check for even numbers
    if n % 2 == 0:
        return n == 2
    # Only test odd divisors
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True
